Content-Disposition: attachment; filename="fluid.demos.ai.noteImageGen"
Content-Description: layer

<script>
// Composition of fluid.demos.closestNoteFinder and fluid.demos.imageGenerator: move this widget close
// to a sticky note and press "Find Image" to search Pixabay for an image matching the note's text
fluid.def("fluid.demos.ai.noteImageGen", {
    $layers: "fluid.topLevelWidget",
    preferredSize: {
        w: 640,
        h: 480
    },
    finder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            // A subcomponent has no tldraw shape of its own, so it borrows the umbrella's canvas bounds
            hostBounds: "{noteImageGen}.hostBounds"
        }
    },
    imageGen: {
        $component: {
            $layers: "fluid.demos.imageGenerator",
            // The closest note's text becomes the search prompt, tracking it as the widget moves
            state: {prompt: "{finder}.noteText"}
        }
    }
});
</script>

<template>
    <div class="nig">
        <div @id="finder"></div>
        <div @id="imageGen"></div>
    </div>
</template>

<style>
.nig {
    display: flex;
    gap: 12px;
    height: 100%;
}

/* Sized structurally, since each subcomponent's own root element merges into its @id container */
.nig > div {
    height: 100%;
    min-height: 0;
}

.nig > div:first-child {
    flex: 0 0 240px;
}

.nig > div:last-child {
    flex: 1 1 auto;
    min-width: 0;
}
</style>
